<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
{
const grid=document.querySelector('#atcFlightplanForm .atc-fpl-grid');
if(grid){const label=document.createElement('label');label.textContent=<?php echo json_encode(t('flightplan_communication')); ?>;const select=document.createElement('select');select.name='communication_mode';[['VOICE',<?php echo json_encode(t('flightplan_communication_voice')); ?>],['RECEIVE_ONLY',<?php echo json_encode(t('flightplan_communication_receive_only')); ?>],['TEXT_ONLY',<?php echo json_encode(t('flightplan_communication_text_only')); ?>]].forEach(([value,text])=>{const option=document.createElement('option');option.value=value;option.textContent=text;select.appendChild(option);});label.appendChild(select);grid.insertBefore(label,grid.children[2]||null);}
}
if(!window.__vfnAtcDuplicate){
document.getElementById('fullscreenButton').addEventListener('click',function(){document.documentElement.requestFullscreen?.().catch(()=>{});});
const atcOptionsButton=document.getElementById('atcOptionsButton'),atcOptionsMenu=document.getElementById('atcOptionsMenu'),atcWindowsButton=document.getElementById('atcWindowsButton'),atcWindowsMenu=document.getElementById('atcWindowsMenu');
atcOptionsButton.addEventListener('click',event=>{event.stopPropagation();atcWindowsMenu.hidden=true;atcOptionsMenu.hidden=!atcOptionsMenu.hidden;});
atcWindowsButton.addEventListener('click',event=>{event.stopPropagation();atcOptionsMenu.hidden=true;atcWindowsMenu.hidden=!atcWindowsMenu.hidden;});
atcOptionsMenu.addEventListener('click',event=>event.stopPropagation());
atcWindowsMenu.addEventListener('click',event=>event.stopPropagation());
document.addEventListener('click',()=>{atcOptionsMenu.hidden=true;atcWindowsMenu.hidden=true;});
document.getElementById('closeAtcButton').addEventListener('click',async function(){this.disabled=true;try{await fetch('execute/atc_session_stop.php',{method:'POST',keepalive:true});}catch(error){}try{window.close();}catch(error){}setTimeout(()=>{if(!window.closed)window.location.replace('index.php');},120);});
const atcInstanceId=window.__vfnAtcInstanceId;const detachedAtcWindows=new Set();let atcChannel=null;
function writeAtcHeartbeat(){localStorage.setItem('vfn-atc-client-active',JSON.stringify({instance:atcInstanceId,timestamp:Date.now()}));}
function focusActiveAtcWindow(){for(const popup of detachedAtcWindows){if(popup&&!popup.closed){popup.focus();return;}}window.focus();}
writeAtcHeartbeat();const atcHeartbeatTimer=setInterval(writeAtcHeartbeat,1000);
if(typeof BroadcastChannel!=='undefined'){atcChannel=new BroadcastChannel('vfn-atc-client');atcChannel.addEventListener('message',event=>{if(event.data?.type==='focus')focusActiveAtcWindow();});}
window.addEventListener('storage',event=>{if(event.key==='vfn-atc-focus-request')focusActiveAtcWindow();});
window.addEventListener('beforeunload',()=>{clearInterval(atcHeartbeatTimer);atcChannel?.close();for(const popup of detachedAtcWindows){try{popup.close();}catch(error){}}try{const active=JSON.parse(localStorage.getItem('vfn-atc-client-active')||'null');if(active?.instance===atcInstanceId)localStorage.removeItem('vfn-atc-client-active');}catch(error){}});
function syncAtcScalesToDocument(targetDocument){
    if(!targetDocument?.documentElement)return;
    const fontScale=Math.max(.75,Math.min(1.5,(Number(localStorage.getItem('vfn-atc-font-scale'))||100)/100));
    const windowScale=Math.max(.75,Math.min(1.5,(Number(localStorage.getItem('vfn-atc-window-scale'))||100)/100));
    const backgroundOpacity=Math.max(10,Math.min(100,Number(localStorage.getItem('vfn-atc-background-opacity'))||90));
    targetDocument.documentElement.style.setProperty('--atc-font-scale',String(fontScale));
    targetDocument.documentElement.style.setProperty('--atc-window-scale',String(windowScale));
    targetDocument.documentElement.style.setProperty('--radar-black-opacity',String(backgroundOpacity/100));
    targetDocument.documentElement.style.setProperty('--radar-map-opacity',String((100-backgroundOpacity)/100));
}
function syncDetachedAtcScales(){
    for(const detachedWindow of detachedAtcWindows){
        try{if(detachedWindow&&!detachedWindow.closed)syncAtcScalesToDocument(detachedWindow.document);}catch(error){}
    }
}
