async function respondAtcHandoff(handoff,accept){
    const body=new URLSearchParams({callsign:String(handoff.pilot_callsign||''),request_id:String(handoff.id||0),action:accept?'handoff-accept':'handoff-reject'}),response=await fetch('execute/atc_initial_contact.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body}),data=await response.json();
