    appendAtcChatMessage({time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),sender:'SYSTEM',text:(accept?<?php echo json_encode(t('atc_handoff_accepted_receiver')); ?>:<?php echo json_encode(t('atc_handoff_rejected_receiver')); ?>).replace('%callsign%',String(handoff.pilot_callsign||'')).replace('%source%',String(handoff.source_callsign||''))});
