async function handleAtcHandoffs(handoffs){
    for(const handoff of Array.isArray(handoffs)?handoffs:[]){
        const key=String(handoff.id||0)+':'+String(handoff.status||'');if(atcHandoffSeen.has(key))continue;atcHandoffSeen.add(key);
        if(handoff.direction==='incoming'&&handoff.status==='pending'){
            appendAtcChatMessage({time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),sender:'SYSTEM',text:<?php echo json_encode(t('atc_handoff_incoming_chat')); ?>.replace('%callsign%',String(handoff.pilot_callsign||'')).replace('%source%',String(handoff.source_callsign||''))});
            playAtcHandoffAlert();
            const accepted=confirm(<?php echo json_encode(t('atc_handoff_confirm')); ?>.replace('%callsign%',String(handoff.pilot_callsign||'')).replace('%source%',String(handoff.source_callsign||'')));
            try{await respondAtcHandoff(handoff,accepted);}catch(error){alert(String(error.message||error));}
        }else if(handoff.direction==='outgoing'&&['accepted','rejected'].includes(String(handoff.status||''))){
            appendAtcChatMessage({time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),sender:'SYSTEM',text:(handoff.status==='accepted'?<?php echo json_encode(t('atc_handoff_accepted_sender')); ?>:<?php echo json_encode(t('atc_handoff_rejected_sender')); ?>).replace('%callsign%',String(handoff.pilot_callsign||'')).replace('%target%',String(handoff.target_callsign||''))});
            await pollAtcTraffic();
