    }
}
async function pollAtcOperationalEvents(initialize=false){
    if(!currentAtcSession||atcOperationalEventRequestInFlight)return;
    atcOperationalEventRequestInFlight=true;
    try{
        const query=initialize?'?initialize=1':'?since_id='+encodeURIComponent(String(atcOperationalEventSinceId||0));
        const response=await fetch('execute/atc_operational_events.php'+query,{cache:'no-store',credentials:'same-origin'}),data=await response.json();
        if(!response.ok||!data.success)return;
        const events=Array.isArray(data.events)?data.events:[];
        for(const event of events){
            const id=Number(event.id||0);
            if(id<=atcOperationalEventSinceId)continue;
            if(String(event.event_type||'')==='atis_runway_changed'){
                const airport=String(event.airport_icao||''),oldValue=String(event.old_value||''),newValue=String(event.new_value||'');
                appendAtcChatMessage({
                    time:new Date(String(event.created_at||'').replace(' ','T')).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),
                    sender:'SYSTEM',
                    text:'<?php echo addslashes(t('atc_atis_runway_changed')); ?>'.replace('%airport%',airport).replace('%old%',oldValue).replace('%new%',newValue)
                });
                if(airport&&newValue)atisKnownRunways.set(airport,newValue);
                setTimeout(pollAtcMetars,100);
            }
            atcOperationalEventSinceId=Math.max(atcOperationalEventSinceId,id);
        }
        await handleAtcHandoffs(data.handoffs);
        atcOperationalEventSinceId=Math.max(atcOperationalEventSinceId,Number(data.last_id||0));
    }catch(error){}finally{atcOperationalEventRequestInFlight=false;}
}
