                L.marker(point,{icon:airportLayoutIcon(name),interactive:false,keyboard:false}).addTo(labels);
            }
        });
        const nearestTaxiPoint=point=>{
            const lat=Number(point[0]),lon=Number(point[1]),scale=Math.cos(lat*Math.PI/180),px=lon*scale,py=lat;let best=null,bestDistance=Infinity;
