let radarSectorLayoutTimer=null,radarSectorLayoutRequest=0,radarSectorLayoutKey='',radarSectorLayoutSessionKey='',radarSectorLayoutAbortController=null,radarSectorLayoutFetchBounds=null;
const radarSectorLayouts=new Map();
function scheduleSectorAirportLayouts(){
    if(radarMapMaterialLoading)return;
    const position=String(currentAtcSession?.position_code||'').toUpperCase();
    if(!['APP','DEP','CTR'].includes(position))return;
    clearTimeout(radarSectorLayoutTimer);
    radarSectorLayoutTimer=setTimeout(()=>loadSectorAirportGroundLayouts(currentAtcSession,false),220);
}
async function loadSectorAirportGroundLayouts(session,force=false){
    if(!radarMap)return;
    const sessionKey=String(session?.callsign||'')+'|'+String(session?.station_code||'')+'|'+String(session?.position_code||'');
    if(sessionKey!==radarSectorLayoutSessionKey){
        if(radarSectorLayoutAbortController)radarSectorLayoutAbortController.abort();
        radarSectorLayoutSessionKey=sessionKey;
        radarSectorLayoutKey='';
        radarSectorLayoutFetchBounds=null;
        radarSectorLayouts.clear();
        clearAirportGroundLayout();
    }
    // Keep the completed layout in memory while zoomed out. Visibility is
    // controlled separately, so zooming back in is instant and cannot leave a
    // temporary empty map while the same files are downloaded again.
    if(radarMap.getZoom()<10){refreshAirportLayoutVisibility();return;}
    const visibleBounds=radarMap.getBounds();
    if(!force&&radarSectorLayoutFetchBounds&&radarSectorLayoutFetchBounds.contains(visibleBounds))return;
    const bounds=visibleBounds.pad(.28),params=new URLSearchParams({
        south:String(bounds.getSouth()),north:String(bounds.getNorth()),
        west:String(bounds.getWest()),east:String(bounds.getEast()),
        scope:String(currentAtcSession?.callsign||radarSectorLayoutSessionKey||'default')
    });
    const request=++radarSectorLayoutRequest;
    if(radarSectorLayoutAbortController)radarSectorLayoutAbortController.abort();
    radarSectorLayoutAbortController=new AbortController();
    try{
        const response=await fetch('execute/atc_layout_airports.php?'+params.toString(),{cache:'default',credentials:'same-origin',signal:radarSectorLayoutAbortController.signal}),payload=await response.json();
        if(!response.ok||!payload.success)throw new Error(payload.message||'airport_layout_scope_failed');
        radarSectorLayoutFetchBounds=bounds;
        const airports=Array.isArray(payload.airports)?payload.airports:[],key=airports.map(item=>String(item.icao||'')).sort().join(',');
        if(!force&&key===radarSectorLayoutKey)return;
        const candidates=airports.slice(0,120),missing=candidates.filter(airport=>!radarSectorLayouts.has(String(airport.icao||'').toUpperCase()));
        for(let offset=0;offset<missing.length;offset+=8){
            if(request!==radarSectorLayoutRequest)return;
            const batch=await Promise.all(missing.slice(offset,offset+8).map(airport=>{
                const icao=String(airport.icao||'').toUpperCase();
                return icao?loadAirportGroundLayout({...session,station_code:icao,position_code:'APP'},true):null;
            }));
            batch.filter(Boolean).forEach(layout=>radarSectorLayouts.set(layout.icao,layout));
        }
        if(request!==radarSectorLayoutRequest)return;
        const base=L.layerGroup(),labels=L.layerGroup(),stands=L.layerGroup(),loaded=[];
        candidates.forEach(airport=>{const layout=radarSectorLayouts.get(String(airport.icao||'').toUpperCase());if(!layout)return;
            layout.base.getLayers().forEach(layer=>base.addLayer(layer));
            layout.labels.getLayers().forEach(layer=>labels.addLayer(layer));
            layout.stands.getLayers().forEach(layer=>stands.addLayer(layer));
            loaded.push(layout.icao);
        });
        clearAirportGroundLayout();radarAirportLayoutLayer=base;radarAirportLabelLayer=labels;radarAirportStandLayer=stands;
        radarAirportLayoutIcao=loaded.join(',');radarSectorLayoutKey=key;
        if(loaded.length){radarAirportLayoutBadge=document.createElement('div');radarAirportLayoutBadge.className='airport-layout-badge';radarAirportLayoutBadge.textContent=loaded.length+' AIRPORT LAYOUTS';document.getElementById('atcRadarMap').appendChild(radarAirportLayoutBadge);}
        refreshAirportLayoutVisibility();
    }catch(error){if(error?.name!=='AbortError'&&request===radarSectorLayoutRequest)console.warn('Sector airport layouts unavailable',error);}
}
function atcNavigationIcon(point){const identifier=escapeText(point.identifier||'');return L.divIcon({className:'',html:'<div class="atc-nav-point '+(point.kind==='navaid'?'navaid':'waypoint')+'">'+identifier+'</div>',iconSize:[100,14],iconAnchor:[4,7]});}
