    radarNavigationPoints=points;radarNavigationLayer.setPoints(points);try{sessionStorage.setItem(cacheKey,JSON.stringify({timestamp:Date.now(),points}));}catch(error){}if(status)status.textContent=radarNavigationVisible?radarNavigationStatusText('points',points.length):radarNavigationStatusText('hidden');
