        }
    }catch(error){console.error(error);}
    const savedViewInsideScope=!radarFirLayer||!radarFirLayer.getLayers().length||radarFirLayer.getBounds().contains(savedMapView?.center||[0,0]);
    if(savedMapView&&savedViewInsideScope){
