function renderAtcTrafficList(){
    const list=document.getElementById('radarTrafficList');if(!list)return;
    document.querySelectorAll('#radarTrafficTabs .traffic-tab').forEach(button=>button.classList.toggle('active',button.dataset.trafficTab===atcTrafficTab));
    ['inbound','outbound','through'].forEach(tab=>{const node=document.querySelector('[data-traffic-count="'+tab+'"]');if(node)node.textContent=String(atcTrafficRows.filter(pilot=>trafficMatchesTab(pilot,tab)).length);});
