        const transponderOn=Number(pilot.transponder_mode)>=2,latitude=Number(pilot.latitude),longitude=Number(pilot.longitude),assumed=Number(pilot.assumed_by_me)===1,assignedTo=String(pilot.assumed_by||'').trim(),assignment=assignedTo||(assumed?String(currentAtcSession?.callsign||'').trim():''),clearance=atcClearanceSummary(pilot),distance=Number(pilot.distance_nm);
        const row=document.createElement('button');row.type='button';row.className='traffic-row radar-traffic-jump'+(assignment?' is-assigned':'');row.dataset.callsign=String(pilot.callsign||'').trim();
        row.innerHTML='<span class="traffic-row-primary"><strong>'+escapeText(transponderOn?pilot.callsign:'◆')+' · '+escapeText(pilot.aircraft_icao||'')+'</strong><span class="traffic-row-meta">'+Math.round(Number(pilot.altitude||0))+' ft'+(Number.isFinite(distance)?' · '+distance.toFixed(1)+' NM':'')+'</span></span><span class="traffic-route">'+escapeText(pilot.pilot_name||'–')+' · '+escapeText(pilot.departure_airport||'ZZZZ')+' &gt; '+escapeText(pilot.arrival_airport||'ZZZZ')+'</span>'+(assignment?'<span class="traffic-route traffic-assignment">['+escapeText(assignment)+']</span>':'')+(clearance?'<span class="traffic-route radar-tag-clearance">'+atcClearanceSummaryHtml(pilot)+'</span>':'');
        const warning=emergencySquawkLabel(pilot);if(warning){row.classList.add('squawk-emergency');const note=document.createElement('span');note.className='radar-emergency-text';note.textContent=normalizedSquawk(pilot)+' · '+warning;row.appendChild(note);}
