let atcTrafficRequestInFlight=false;
async function pollAtcTraffic(){
    if(atcTrafficRequestInFlight||!currentAtcSession)return;
    atcTrafficRequestInFlight=true;
    try{
        const response=await fetch('execute/atc_traffic.php',{cache:'no-store'}),data=await response.json();
        if(!response.ok||!data.success)return;
        initializeRadarMap();loadRadarLabelOffsets();
        if(data.center&&currentAtcSession?.position_code!=='CTR')applyAirportRadarLimits(currentAtcSession,data.center);
        const traffic=Array.isArray(data.traffic)?data.traffic:[],active=new Set(traffic.map(pilot=>String(pilot.callsign||'').trim()).filter(Boolean));
        Array.from(radarTargets.keys()).forEach(callsign=>{if(!active.has(callsign))removeRadarTarget(callsign);});
        traffic.forEach(pilot=>{
            ensureAtcSidRunwayCheck(pilot);
            const transponderOn=Number(pilot.transponder_mode)>=2,latitude=Number(pilot.latitude),longitude=Number(pilot.longitude),assumed=Number(pilot.assumed_by_me)===1,assignedTo=String(pilot.assumed_by||'').trim(),assignment=assignedTo||(assumed?String(currentAtcSession?.callsign||'').trim():''),clearance=atcClearanceSummary(pilot);
            checkAtcRunwayAtisWarning(pilot);
            updateRadarTarget(pilot,transponderOn);
        });
        atcTrafficRows=traffic;renderAtcTrafficList();
    }catch(error){}finally{atcTrafficRequestInFlight=false;}
}
