function appendAtcChatMessage(message){const id=Number(message.id||0);if(id>0&&atcChatRenderedIds.has(id))return;if(id>0)atcChatRenderedIds.add(id);const line=document.createElement('div');line.className='atc-chat-line';line.innerHTML='<span class="atc-chat-time">'+escapeText(message.time||'')+'</span><span class="atc-chat-sender">'+escapeText(message.sender||'–')+'</span><span>'+escapeText(message.text||'')+'</span>';atcChatLog.appendChild(line);while(atcChatLog.children.length>200)atcChatLog.firstElementChild?.remove();atcChatLog.scrollTop=atcChatLog.scrollHeight;}
function selectAtcChatChannel(channel,reset=true){
    atcChatChannel=['frequency','nearby','unicom','private'].includes(channel)?channel:'frequency';
    document.querySelectorAll('.atc-chat-tab').forEach(button=>button.classList.toggle('active',button.dataset.channel===atcChatChannel));
    document.querySelector('.atc-chat-tab[data-channel="'+atcChatChannel+'"]')?.classList.remove('has-unread');
    atcChatPrivateTools.hidden=atcChatChannel!=='private';
    if(atcChatChannel==='unicom')atcChatFrequency.value='122.800';
    else if(atcChatChannel==='frequency')atcChatFrequency.value=normalizeAtcFrequency(currentAtcSession?.frequency||'')||'';
    const assignedFrequency=normalizeAtcFrequency(currentAtcSession?.frequency||'');
    if(atcChatFrequencyTab)atcChatFrequencyTab.textContent=atcChatFrequencyTab.dataset.label+(assignedFrequency?' · '+assignedFrequency+' MHz':'');
    if(reset)pollAtcChat(true);
}
document.querySelectorAll('.atc-chat-tab').forEach(button=>button.addEventListener('click',()=>selectAtcChatChannel(button.dataset.channel||'frequency')));
async function pollAtcChat(reset=false){
    const frequency=atcChatChannel==='unicom'?'122.800':(atcChatChannel==='frequency'?normalizeAtcFrequency(atcChatFrequency.value):'');
    if((atcChatChannel==='frequency'&&!frequency)||atcChatRequestInFlight)return;
    const channelKey=atcChatChannel+'|'+frequency;
    if(reset||channelKey!==atcChatFrequencyValue){atcChatFrequencyValue=channelKey;atcChatSinceId=0;atcChatLog.innerHTML='';atcChatRenderedIds.clear();}
    atcChatRequestInFlight=true;
    try{const query=new URLSearchParams({channel:atcChatChannel,frequency,since_id:String(atcChatSinceId)}),response=await fetch('execute/atc_chat.php?'+query.toString(),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'chat_failed');(data.messages||[]).forEach(appendAtcChatMessage);atcChatSinceId=Math.max(atcChatSinceId,Number(data.last_id||0));}catch(error){}finally{atcChatRequestInFlight=false;pollAtcChatUnread();}
}
