async function pollAtcMetars(){if(atcMetarRequestInFlight||!currentAtcSession)return;atcMetarRequestInFlight=true;try{const response=await fetch('execute/atc_metar_watch.php?_='+Date.now(),{cache:'no-store',credentials:'same-origin'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'metar_failed');const incoming=Array.isArray(data.reports)?data.reports:[],compareKeys=['wind_direction','wind_speed','wind_gust','visibility','weather','clouds','temperature','dewpoint','qnh','arrival_runways','departure_runways'];incoming.forEach(report=>{const raw=String(report.raw||''),previous=atcMetarPrevious.get(report.icao),fields=new Set(previous?compareKeys.filter(key=>String(previous[key]??'')!==String(report[key]??'')):[]),weatherChanged=previous&&String(previous.raw||'')!==''&&raw!==''&&String(previous.raw||'')!==raw,runwayChanged=fields.has('arrival_runways')||fields.has('departure_runways');if(previous&&(weatherChanged||runwayChanged)){if(fields.has('dewpoint'))fields.add('temperature');atcMetarPrior.set(report.icao,previous);atcMetarChanged.add(report.icao);atcMetarChangedFields.set(report.icao,fields);}atcMetarPrevious.set(report.icao,report);});atcMetarReports=incoming;atcMetarPanel.querySelector('#atcMetarUpdated').textContent=data.updated_at||'–';saveAtcMetarState();renderAtcMetars();refreshAirportWatchPanels();if(!incoming.length&&data.scope){atcMetarPanel.querySelector('#atcMetarSummary').textContent='0 · '+String(data.scope.station||'?')+'_'+String(data.scope.position||'?')+' · '+Number(data.scope.features||0)+' Sektoren';}clearTimeout(atcMetarRetryTimer);if(!incoming.length&&atcMetarEmptyRetries<3){atcMetarEmptyRetries++;atcMetarRetryTimer=setTimeout(pollAtcMetars,2000);}else if(incoming.length)atcMetarEmptyRetries=0;}catch(error){atcMetarPanel.querySelector('#atcMetarSummary').textContent=String(error.message||error);clearTimeout(atcMetarRetryTimer);if(atcMetarEmptyRetries<3){atcMetarEmptyRetries++;atcMetarRetryTimer=setTime