function decodeAtcPcm(base64){const binary=atob(base64),samples=new Float32Array(Math.floor(binary.length/2));for(let i=0;i<samples.length;i++){let value=binary.charCodeAt(i*2)|(binary.charCodeAt(i*2+1)<<8);if(value>=32768)value-=65536;samples[i]=value/32768;}return samples;}
function encodeAtcPcm(samples){const bytes=new Uint8Array(samples.length*2),view=new DataView(bytes.buffer);for(let i=0;i<samples.length;i++){const sample=Math.max(-1,Math.min(1,samples[i]));view.setInt16(i*2,sample<0?sample*32768:sample*32767,true);}let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary);}
function downsampleAtc(input,inputRate,outputRate=16000){if(outputRate>=inputRate)return new Float32Array(input);const ratio=inputRate/outputRate,result=new Float32Array(Math.max(1,Math.round(input.length/ratio)));for(let i=0;i<result.length;i++){const start=Math.floor(i*ratio),end=Math.min(input.length,Math.floor((i+1)*ratio));let sum=0,count=0;for(let j=start;j<end;j++){sum+=input[j];count++;}result[i]=count?sum/count:0;}return result;}
function setAtcVoiceMeter(kind,value){const percent=Math.max(0,Math.min(100,Math.round(value)));const fill=document.getElementById('atcVoice'+kind+'Fill'),text=document.getElementById('atcVoice'+kind+'Percent');if(fill)fill.style.width=percent+'%';if(text)text.textContent=percent+'%';}
async function playAtcVoice(payload){if(payload.codec!=='pcm16'||typeof payload.payload!=='string')return;const samples=decodeAtcPcm(payload.payload);let sum=0;for(const sample of samples)sum+=sample*sample;setAtcVoiceMeter('Rx',Math.sqrt(sum/Math.max(1,samples.length))*450);voicePlaybackContext=voicePlaybackContext||new(window.AudioContext||window.webkitAudioContext)();const output=document.getElementById('atcVoiceOutputDevice')?.value||'';if(output&&typeof voicePlaybackContext.setSinkId==='function')try{await voicePlaybackContext.setSinkId(output);}catch(error){}if(voicePlaybackContext.state==='suspended')await voicePlaybackContext.resume();const buffer=voicePlaybackContext.createBuffer(1,samples.length,Number(payload.sampleRate||16000));buffer.copyToChannel(samples,0);const source=voicePlaybackContext.createBufferSource();source.buffer=buffer;source.connect(voicePlaybackContext.destination);if(voicePlaybackTime<voicePlaybackContext.currentTime||voicePlaybackTime>voicePlaybackContext.currentTime+.75)voicePlaybackTime=voicePlaybackContext.currentTime+.04;source.start(voicePlaybackTime);voicePlaybackTime+=buffer.duration;setTimeout(()=>setAtcVoiceMeter('Rx',0),Math.max(100,buffer.duration*1000+80));}
function connectAtcVoice(){const state=document.getElementById('atcVoiceState');const frequency=normalizeAtcFrequency(document.getElementById('atcVoiceFrequency').value);const reference=document.getElementById('atcVoiceReference').value.trim().toUpperCase();document.getElementById('atcVoiceFrequency').value=frequency;if(!ATC_VOICE_TOKEN||!frequency){state.textContent='<?php echo addslashes(t('atc_voice_disconnected')); ?>';return;}if(atcVoiceSocket)atcVoiceSocket.close();atcVoiceSocket=new WebSocket(ATC_VOICE_URL);atcVoiceSocket.addEventListener('open',()=>atcVoiceSocket.send(JSON.stringify({type:'hello',token:ATC_VOICE_TOKEN,callsign:currentAtcSession.callsign,com1:frequency,com2:frequency,txCom:1})));atcVoiceSocket.addEventListener('message',event=>{let payload;try{payload=JSON.parse(event.data);}catch(error){return;}if(payload.type==='hello'&&payload.success){atcVoiceConnected=true;let attempts=0;const sendMonitor=()=>{if(!atcVoiceSocket||atcVoiceSocket.readyState!==WebSocket.OPEN)return;let center=null;try{center=radarMap?.getCenter?.()||null;}catch(error){}const latitude=Number(center?.lat),longitude=Number(center?.lng);if(frequency!=='122.800'&&(!Number.isFinite(latitude)||!Number.isFinite(longitude))&&attempts++<25){setTimeout(sendMonitor,100);return;}atcVoiceSocket.send(JSON.stringify({type:'monitor',frequency,global:frequency==='122.800',airportIcao:frequency==='122.800'?'':reference,atcSessionReference:true,latitude:Number.isFinite(latitude)?latitude:null,longitude:Number.isFinite(longitude)?longitude:null,rangeNm:50}));};sendMonitor();}if(payload.type==='monitor'&&payload.success)state.textContent='<?php echo addslashes(t('atc_voice_connected')); ?>'+(Number(payload.receiveOnly)?' · <?php echo addslashes(t('atc_voice_receive_only')); ?>':'');if(payload.type==='audio')playAtcVoice(payload).catch(()=>{});if(payload.type==='error')state.textContent=String(payload.message||'Voice error');});atcVoiceSocket.addEventListener('close',()=>{atcVoiceConnected=false;atcVoiceTransmitting=false;setAtcVoiceMeter('Tx',0);state.textContent='<?php echo addslashes(t('atc_voice_disconnected')); ?>';});}
async function setAtcPtt(active){if(Number(currentAtcSession?.is_spectator||currentAtcSession?.spectator))return;if(active===atcVoiceTransmitting)return;if(active&&!atcVoiceConnected){connectAtcVoice();await new Promise(resolve=>setTimeout(resolve,250));}atcVoiceTransmitting=active;const button=document.getElementById('atcVoicePtt');button?.classList.toggle('is-transmitting',active);if(active){const selected=document.getElementById('atcVoiceInputDevice')?.value||'';const audio={channelCount:1,echoCancellation:true,noiseSuppression:true};if(selected)audio.deviceId={exact:selected};atcMicStream=await navigator.mediaDevices.getUserMedia({audio,video:false});atcMicContext=atcMicContext||new(window.AudioContext||window.webkitAudioContext)();await atcMicContext.resume();atcMicSource=atcMicContext.createMediaStreamSource(atcMicStream);atcMicProcessor=atcMicContext.createScriptProcessor(2048,1,1);atcMicGain=atcMicContext.createGain();atcMicGain.gain.value=0;atcMicProcessor.onaudioprocess=event=>{if(!atcVoiceConnected||!atcVoiceTransmitting)return;const input=event.inputBuffer.getChannelData(0);let sum=0;for(const sample of input)sum+=sample*sample;setAtcVoiceMeter('Tx',Math.sqrt(sum/Math.max(1,input.length))*450);const frequency=document.getElementById('atcVoiceFrequency').value.trim();atcVoiceSocket.send(JSON.stringify({type:'audio',codec:'pcm16',sampleRate:16000,frequency,sequence:++atcVoiceSequence,ptt:true,payload:encodeAtcPcm(downsampleAtc(input,atcMicContext.sampleRate))}));};atcMicSource.connect(atcMicProcessor);atcMicProcessor.connect(atcMicGain);atcMicGain.connect(atcMicContext.destination);atcVoiceSocket?.send(JSON.stringify({type:'ptt',active:true,txCom:1,frequency:document.getElementById('atcVoiceFrequency').value.trim()}));}else{setAtcVoiceMeter('Tx',0);atcVoiceSocket?.send(JSON.stringify({type:'ptt',active:false,txCom:1,frequency:document.getElementById('atcVoiceFrequency').value.trim()}));if(atcMicProcessor){atcMicProcessor.disconnect();atcMicProcessor=null;}