function closeRadarMapContextMenu(){const menu=document.getElementById('radarMapContextMenu');if(menu){menu.hidden=true;menu.querySelectorAll('.radar-context-submenu.is-open').forEach(item=>item.classList.remove('is-open'));}radarMapContextLatLng=null;radarMapContextAirport=null;}
function airportAtRadarPoint(latlng){if(!airportWatchEligible()||!radarMap)return null;const clicked=radarMap.latLngToContainerPoint(latlng);let nearest=null,distance=Infinity;atcMetarReports.forEach(report=>{const latitude=Number(report.latitude),longitude=Number(report.longitude);if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;const current=clicked.distanceTo(radarMap.latLngToContainerPoint([latitude,longitude]));if(current<distance){distance=current;nearest=report;}});return distance<=18?nearest:null;}
function openRadarMapContextMenu(event){event.originalEvent?.preventDefault?.();closeRadarContextMenu();const nativeEvent=event.originalEvent||event,menu=document.getElementById('radarMapContextMenu'),airportButton=menu.querySelector('[data-map-command="airport-watch"]');radarMapContextLatLng=event.latlng;radarMapContextAirport=airportAtRadarPoint(event.latlng);document.getElementById('radarMapContextTitle').textContent=radarMapContextAirport?(String(radarMapContextAirport.icao||'')+' · '+String(radarMapContextAirport.name||'')).replace(/ · $/,''):<?php echo json_encode(t('atc_map_context_title')); ?>;airportButton.hidden=!radarMapContextAirport;menu.querySelector('[data-map-command="clear-measure"]').disabled=!radarMeasurementLayer?.getLayers?.().length;menu.hidden=false;const width=260,height=menu.offsetHeight||145,clientX=Number(nativeEvent.clientX||0),clientY=Number(nativeEvent.clientY||0);menu.style.left=Math.max(6,Math.min(window.innerWidth-width-6,clientX))+'px';menu.style.top=Math.max(6,Math.min(window.innerHeight-height-6,clientY))+'px';}
const openRadarMapContextMenuCore=openRadarMapContextMenu;openRadarMapContextMenu=function(event){const trainingMenu=document.querySelector('#radarMapContextMenu [data-submenu="training"]');if(trainingMenu)trainingMenu.hidden=Number(currentAtcSession?.is_trainer||currentAtcSession?.trainer)!==1;openRadarMapContextMenuCore(event);};
function installRadarMapContextMenu(){if(!radarMap||radarMap.__vfnMapContextMenu)return;radarMap.__vfnMapContextMenu=true;radarMap.off('contextmenu');radarMap.on('contextmenu',openRadarMapContextMenu);}
document.getElementById('radarMapContextMenu')?.addEventListener('click',event=>{const command=event.target.closest('button')?.dataset.mapCommand;if(!command)return;if(command==='airport-watch'&&radarMapContextAirport)openAirportWatch(radarMapContextAirport);else if(command==='measure'&&radarMapContextLatLng)startRadarMeasurementAt(radarMapContextLatLng);else if(command==='clear-measure')clearRadarMeasurement();closeRadarMapContextMenu();});
