async function refreshAtcVoiceDevices(requestPermission=false){
  if(!navigator.mediaDevices?.enumerateDevices)return;
  if(requestPermission){try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(track=>track.stop());}catch(error){}}
  const devices=await navigator.mediaDevices.enumerateDevices();
  const input=document.getElementById('atcVoiceInputDevice'),output=document.getElementById('atcVoiceOutputDevice');
  const selectedInput=input.value||localStorage.getItem('vfn-atc-voice-input')||'';
  const selectedOutput=output.value||localStorage.getItem('vfn-atc-voice-output')||'';
  input.innerHTML='<option value="">Systemstandard</option>';output.innerHTML='<option value="">Systemstandard</option>';
  let inputNumber=0,outputNumber=0;
  devices.forEach(device=>{if(device.kind!=='audioinput'&&device.kind!=='audiooutput')return;const option=document.createElement('option');option.value=device.deviceId;if(device.kind==='audioinput'){option.textContent=device.label||('Mikrofon '+(++inputNumber));input.appendChild(option);}else{option.textContent=device.label||('Ausgabe '+(++outputNumber));output.appendChild(option);}});
  input.value=Array.from(input.options).some(option=>option.value===selectedInput)?selectedInput:'';
  output.value=Array.from(output.options).some(option=>option.value===selectedOutput)?selectedOutput:'';
}
