const pollAtcTrafficEmergencyBase=pollAtcTraffic;pollAtcTraffic=async function(){await pollAtcTrafficEmergencyBase();const rows=Array.from(document.querySelectorAll('#radarTrafficList .traffic-row'));radarTargets.forEach(target=>{const warning=emergencySquawkLabel(target.pilot),row=rows.find(item=>item.dataset.callsign===target.callsign);if(!row)return;row.classList.toggle('squawk-emergency',Boolean(warning));row.querySelector('.radar-emergency-text')?.remove();if(warning){const note=document.createElement('span');note.className='radar-emergency-text';note.textContent=normalizedSquawk(target.pilot)+' · '+warning;row.appendChild(note);}});};
function atcConflictDistanceNm(first,second){const toRad=Math.PI/180,lat1=Number(first.latitude)*toRad,lat2=Number(second.latitude)*toRad,dLat=lat2-lat1,dLon=(Number(second.longitude)-Number(first.longitude))*toRad,a=Math.sin(dLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2;return 3440.065*2*Math.atan2(Math.sqrt(a),Math.sqrt(Math.max(0,1-a)));}
function updateAtcConflictWarnings(){const targets=Array.from(radarTargets.values()),conflictCallsigns=new Set(),conflicts=[];for(let firstIndex=0;firstIndex<targets.length;firstIndex++){const first=targets[firstIndex]?.pilot||{};if(Number(first.on_ground)===1)continue;for(let secondIndex=firstIndex+1;secondIndex<targets.length;secondIndex++){const second=targets[secondIndex]?.pilot||{};if(Number(second.on_ground)===1)continue;const coordinates=[first.latitude,first.longitude,second.latitude,second.longitude].map(Number);if(!coordinates.every(Number.isFinite))continue;const horizontal=atcConflictDistanceNm(first,second),vertical=Math.abs(Number(first.altitude||0)-Number(second.altitude||0));if(horizontal<=3&&vertical<=1000){const firstCallsign=String(first.callsign||'----'),secondCallsign=String(second.callsign||'----');conflictCallsigns.add(firstCallsign);conflictCallsigns.add(secondCallsign);conflicts.push({firstCallsign,secondCallsign,horizontal,vertical});}}}const rows=Array.from(document.querySelectorAll('#radarTrafficList .traffic-row'));radarTargets.forEach(target=>{const active=conflictCallsigns.has(target.callsign),row=rows.find(item=>item.dataset.callsign===target.callsign);target.targetMarker?.getElement?.()?.querySelector('.radar-target-diamond')?.classList.toggle('traffic-conflict',active);target.labelMarker?.getElement?.()?.querySelector('.radar-target-label')?.classList.toggle('traffic-conflict',active);row?.classList.toggle('traffic-conflict',active);row?.querySelector('.atc-conflict-row')?.remove();if(active&&row){const related=conflicts.filter(item=>item.firstCallsign===target.callsign||item.secondCallsign===target.callsign),note=document.createElement('span');note.className='atc-conflict-row';note.textContent='KONFLIKT · '+related.map(item=>(item.firstCallsign===target.callsign?item.secondCallsign:item.firstCallsign)+' '+item.horizontal.toFixed(1)+' NM / '+Math.round(item.vertical)+' FT').join(' · ');row.appendChild(note);}});const banner=document.getElementById('atcConflictBanner');if(!banner)return;banner.hidden=conflicts.length===0;banner.textContent=conflicts.length?'⚠ KONFLIKTWARNUNG · '+conflicts.slice(0,3).map(item=>item.firstCallsign+' / '+item.secondCallsign+' · '+item.horizontal.toFixed(1)+' NM · Δ'+Math.round(item.vertical)+' FT').join(' | '):'';}
const pollAtcTrafficConflictBase=pollAtcTraffic;pollAtcTraffic=async function(){await pollAtcTrafficConflictBase();updateAtcConflictWarnings();};
const setSessionDisplayWithTitle=setSessionDisplay;
setSessionDisplay=function(session){setSessionDisplayWithTitle(session);updateAtcWindowTitle(session);const frequency=normalizeAtcFrequency(session?.frequency||document.getElementById('atcVoiceFrequency')?.value||'');document.getElementById('radarOwnFrequency').textContent=frequency?frequency+' MHz':'–';};
document.getElementById('logoutAtcPositionButton').addEventListener('click',()=>{updateAtcWindowTitle(null);});
document.getElementById('logoutAtcPositionButton').addEventListener('click',logoutAtcPosition);
let cpdlcSelectedId=0,cpdlcPoll=null,cpdlcBusy=false,cpdlcData={connections:[],messages:{}};
const cpdlcConnections=document.getElementById('cpdlcConnections'),cpdlcTranscript=document.getElementById('cpdlcTranscript'),cpdlcStatus=document.getElementById('cpdlcStatus'),cpdlcForm=document.getElementById('cpdlcForm'),cpdlcMessage=document.getElementById('cpdlcMessage');
function renderCpdlc(){
 const connections=cpdlcData.connections||[];if(!connections.some(c=>Number(c.id)===cpdlcSelectedId))cpdlcSelectedId=connections.length?Number(connections[0].id):0;
 cpdlcConnections.replaceChildren(...connections.map(c=>{const b=document.createElement('button');b.type='button';b.className='cpdlc-connection '+String(c.state)+(Number(c.id)===cpdlcSelectedId?' active':'');b.textContent=String(c.pilot_callsign)+' · '+String(c.state).toUpperCase();b.onclick=()=>{cpdlcSelectedId=Number(c.id);renderCpdlc();};return b;}));
 const selected=connections.find(c=>Number(c.id)===cpdlcSelectedId),messages=(cpdlcData.messages||{})[String(cpdlcSelectedId)]||[];
 cpdlcTranscript.replaceChildren(...messages.map(m=>{const d=document.createElement('div');d.className='cpdlc-message '+String(m.sender_role);const s=document.createElement('small');s.textContent=String(m.time||'')+' · '+String(m.sender_role||'').toUpperCase()+' · '+String(m.status||'').toUpperCase();const t=document.createElement('div');t.textContent=String(m.message_text||'');d.append(s,t);return d;}));cpdlcTranscript.scrollTop=cpdlcTranscript.scrollHeight;
 document.querySelectorAll('[data-cpdlc-action]').forEach(b=>{const a=b.dataset.cpdlcAction;if(!selected){b.disabled=true;return;}if(a==='accept'||a==='reject')b.disabled=selected.state!=='requested';else if(a==='delete')b.disabled=!['closed','rejected'].includes(String(selected.state));else b.disabled=selected.state!=='connected';});cpdlcForm.querySelector('button').disabled=!selected||selected.state!=='connected';
 const gatewayError=cpdlcData.gateway&&cpdlcData.gateway.last_error?String(cpdlcData.gateway.last_error):'';
 cpdlcStatus.textContent=selected?String(selected.pilot_callsign)+' · '+String(selected.station_code)+' · '+String(selected.state)+' · '+String(selected.transport||'vfn').toUpperCase():(cpdlcData.hoppie_enabled?(gatewayError?'HOPPIE ERROR: '+gatewayError:'HOPPIE READY'):'HOPPIE DISABLED');
}
async function pollCpdlc(){if(cpdlcBusy||!currentAtcSession)return;cpdlcBusy=true;try{const r=await fetch('execute/atc_cpdlc.php?_='+Date.now(),{cache:'no-store',credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||'cpdlc_failed');cpdlcData=d;renderCpdlc();}catch(e){cpdlcStatus.textContent=String(e.message||e);}finally{cpdlcBusy=false;}}
async function cpdlcPost(action,extra={}){if(!cpdlcSelectedId)return;const body=new URLSearchParams({action,connection_id:String(cpdlcSelectedId),...extra});const r=await fetch('execute/atc_cpdlc.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||'cpdlc_failed');cpdlcData=d;renderCpdlc();}
document.querySelectorAll('[data-cpdlc-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.cpdlcAction;if(action==='delete'&&!confirm('Delete this closed CPDLC history?'))return;cpdlcPost(action).then(()=>{if(action==='delete'){cpdlcSelectedId=0;renderCpdlc();}}).catch(e=>cpdlcStatus.textContent=String(e.message||e));}));
const cpdlcClearanceButton=document.querySelector('[data-cpdlc-clearance]');
if(cpdlcClearanceButton&&!document.querySelector('[data-cpdlc-position]')&&!document.querySelector('[data-cpdlc-template="REQUEST POSITION REPORT"]')){
  const positionButton=document.createElement('button');
  positionButton.type='button';positionButton.dataset.cpdlcPosition='1';positionButton.dataset.cpdlcTemplate='REQUEST POSITION REPORT';positionButton.textContent='POSITION';
  cpdlcClearanceButton.before(positionButton);
}
document.querySelectorAll('[data-cpdlc-template]').forEach(b=>b.addEventListener('click',()=>{cpdlcMessage.value=b.dataset.cpdlcTemplate;cpdlcMessage.focus();}));
function buildCpdlcClearance(pilot){
 const callsign=String(pilot?.callsign||'').trim().toUpperCase(),runway=String(pilot?.cleared_departure_runway||'').trim().toUpperCase(),sid=String(pilot?.cleared_sid||'').trim().toUpperCase(),altitude=String(pilot?.cleared_altitude||'').trim().toUpperCase(),squawk=normalizedSquawk(pilot),destinationCode=String(pilot?.arrival_airport||'').trim().toUpperCase();
 const procedureName=value=>String(value||'').replace(/^([A-Z]{2,})(\d+[A-Z]?)$/,'$1 $2');
 const airportLabel=()=>{const municipality=String(pilot?.arrival_municipality||'').trim(),name=String(pilot?.arrival_airport_name||'').trim(),raw=municipality||name||destinationCode;return raw.replace(/\s+(?:INTERNATIONAL\s+)?AIRPORT$/i,'').trim().toUpperCase();};
 const climbText=()=>{if(!altitude)return'';const compact=altitude.replace(/\s+/g,'');const flightLevel=compact.match(/^(?:FL|F)(\d{2,3})$/);if(flightLevel)return'CLIMB FLIGHT LEVEL '+flightLevel[1];const feet=compact.match(/^(\d{3,5})(?:FT|FEET)?$/);return feet?'CLIMB '+feet[1]+' FEET':'CLIMB '+altitude;};
 const parts=[];
 if(callsign)parts.push(callsign);
 parts.push('START-UP APPROVED');
 const destination=airportLabel();
 let cleared='CLEARED'+(destination?' TO '+destination:'');
 if(sid)cleared+=' VIA '+procedureName(sid)+' DEPARTURE';
 parts.push(cleared);
 if(runway)parts.push('DEPARTURE RUNWAY '+runway);
 parts.push('FLIGHT PLANNED ROUTE');
 const climb=climbText();if(climb)parts.push(climb);
 if(squawk&&squawk!=='0000')parts.push('SQUAWK '+squawk);
 return parts.join(', ')+'.';
}
document.querySelector('[data-cpdlc-clearance]')?.addEventListener('click',()=>{
 const selected=(cpdlcData.connections||[]).find(connection=>Number(connection.id)===cpdlcSelectedId),callsign=String(selected?.pilot_callsign||'').trim().toUpperCase(),pilot=atcTrafficRows.find(row=>String(row.callsign||'').trim().toUpperCase()===callsign),message=buildCpdlcClearance(pilot);
 if(!selected){cpdlcStatus.textContent='SELECT A CPDLC CONNECTION';return;}
 if(!pilot){cpdlcStatus.textContent='NO LIVE FLIGHT DATA FOR '+callsign;return;}
 if(!message){cpdlcStatus.textContent='NO CLEARANCE DATA FOR '+callsign;return;}
 cpdlcMessage.value=message;cpdlcMessage.focus();cpdlcStatus.textContent='CLEARANCE PREPARED FOR '+callsign;
});
cpdlcForm.addEventListener('submit',e=>{e.preventDefault();const message=cpdlcMessage.value.trim();if(!message)return;cpdlcPost('send',{message,response_options:'WILCO,UNABLE,STANDBY,ROGER'}).then(()=>cpdlcMessage.value='').catch(x=>cpdlcStatus.textContent=String(x.message||x));});
cpdlcPoll=setInterval(pollCpdlc,2500);window.addEventListener('beforeunload',()=>clearInterval(cpdlcPoll));
const initialAtcSession=<?php echo json_encode($resumableSession, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>;
if(initialAtcSession)enterRadar(initialAtcSession);else resumeAtcSession();
<?php endif; ?>
}
</script>
</body></html>
